thematic_ui <- function() tabPanel("Mapa tem\u00e1tico", model_analysis_ui("thematic"),
  panel("Configurar el an\u00e1lisis",
    ui_subblock("Elegir el origen y los filtros",
      selectInput("thematic_field", "Origen de los t\u00e9rminos", c("Palabras clave declaradas / campo asignado en 02" = "keywords", "Vocabulario preparado / t\u00e9rminos retenidos del texto" = "text")),
      uiOutput("thematic_input_coverage"),
      fluidRow(column(4, numericInput("thematic_presence", "Presencia m\u00ednima / documentos", 2, 1, 10000)),
        column(4, numericInput("thematic_terms", "M\u00e1ximo de t\u00e9rminos / m\u00e1s presentes", 100, 2, 150)),
        column(4, numericInput("thematic_shared", "Copresencias m\u00ednimas / documentos", 1, 1, 10000)))),
    ui_subblock("Definir las comunidades y calcular",
      fluidRow(column(6, numericInput("thematic_resolution", "Resoluci\u00f3n de Louvain", 1, .1, 3, step = .1)),
        column(6, numericInput("thematic_seed", "Semilla", 2026, 1, 2147483647))),
      hint("Se normalizan las copresencias con el \u00edndice de equivalencia. No se limita el n\u00famero de conexiones por motivos gr\u00e1ficos: todas las que superan el umbral intervienen en el an\u00e1lisis."),
      actionButton("run_thematic", "Calcular mapa tem\u00e1tico", class = "btn-primary run-analysis"))),
  panel("Leer los resultados",
    ui_subblock("Comprobar el estado y leer el mapa", uiOutput("thematic_state"),
      plotOutput("thematic_plot", height = "auto"),
      hint("Los dos ejes son lineales. Los trazos discontinuos se\u00f1alan el valor central de cada medida al ordenar los temas del mapa (mediana). Separan posiciones relativas dentro de este mapa, no niveles universales de calidad. La densidad y la centralidad son \u00edndices, no porcentajes. Las coordenadas de los c\u00edrculos conservan las medidas calculadas. En pantallas estrechas se muestran los identificadores T1, T2, etc.; consulta sus t\u00e9rminos en la tabla.")),
    ui_subblock("Revisar temas, t\u00e9rminos y cobertura",
      tabsetPanel(id = "thematic_tables",
        tabPanel("Temas y medidas", DT::DTOutput("thematic_themes")),
        tabPanel("T\u00e9rminos por tema", DT::DTOutput("thematic_terms_table")),
        tabPanel("Cobertura", DT::DTOutput("thematic_coverage")),
        tabPanel("Selecci\u00f3n y exclusiones", DT::DTOutput("thematic_selection")),
        tabPanel("Conexiones", DT::DTOutput("thematic_edges")))),
    ui_subblock("Guardar el an\u00e1lisis", downloadButton("download_thematic", "Descargar mapa, tablas y reproducci\u00f3n"),
      hint("El ZIP contiene PNG, PDF, tablas, par\u00e1metros y un guion de reproducci\u00f3n. Tambi\u00e9n se incluye en el ZIP de 05 / Entrega cuando el mapa est\u00e1 vigente. La matriz de reproducci\u00f3n contiene t\u00e9rminos e identificadores de documentos."))))
